CREATE TYPE "PayFrequency" AS ENUM ('WEEKLY','FORTNIGHTLY','MONTHLY');
CREATE TYPE "BenefitType" AS ENUM ('RETIREMENT_FUND','MEDICAL_AID','OTHER');
CREATE TYPE "ContributionMethod" AS ENUM ('NONE','FIXED_AMOUNT','PERCENTAGE');
CREATE TYPE "ContributionBasis" AS ENUM ('BASIC_SALARY','PENSIONABLE_SALARY','CUSTOM');
CREATE TABLE "PayrollSettings" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"payFrequency" "PayFrequency" NOT NULL DEFAULT 'MONTHLY',"uifRegistered" BOOLEAN NOT NULL DEFAULT true,"sdlApplicable" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PayrollSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PayrollSettings_organizationId_key" ON "PayrollSettings"("organizationId");
CREATE TABLE "EmployeePayrollProfile" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"taxNumber" TEXT,"basicSalary" DOUBLE PRECISION NOT NULL DEFAULT 0,"pensionableSalary" DOUBLE PRECISION,"hourlyRate" DOUBLE PRECISION,"payFrequency" "PayFrequency" NOT NULL DEFAULT 'MONTHLY',"bankName" TEXT,"bankAccountHolder" TEXT,"bankAccountNumber" TEXT,"bankBranchCode" TEXT,"bankAccountType" TEXT,"bankVerificationStatus" TEXT NOT NULL DEFAULT 'NOT_VERIFIED',"medicalAidDependants" INTEGER NOT NULL DEFAULT 0,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmployeePayrollProfile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmployeePayrollProfile_employeeId_key" ON "EmployeePayrollProfile"("employeeId"); CREATE INDEX "EmployeePayrollProfile_organizationId_idx" ON "EmployeePayrollProfile"("organizationId");
CREATE TABLE "BenefitPlan" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"type" "BenefitType" NOT NULL,"providerName" TEXT,"employeeMethod" "ContributionMethod" NOT NULL DEFAULT 'NONE',"employeeValue" DOUBLE PRECISION NOT NULL DEFAULT 0,"employerMethod" "ContributionMethod" NOT NULL DEFAULT 'NONE',"employerValue" DOUBLE PRECISION NOT NULL DEFAULT 0,"contributionBasis" "ContributionBasis" NOT NULL DEFAULT 'BASIC_SALARY',"active" BOOLEAN NOT NULL DEFAULT true,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BenefitPlan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BenefitPlan_organizationId_name_key" ON "BenefitPlan"("organizationId","name"); CREATE INDEX "BenefitPlan_organizationId_type_idx" ON "BenefitPlan"("organizationId","type");
CREATE TABLE "EmployeeBenefit" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"payrollProfileId" TEXT NOT NULL,"benefitPlanId" TEXT NOT NULL,"membershipNumber" TEXT,"employeeMethodOverride" "ContributionMethod","employeeValueOverride" DOUBLE PRECISION,"employerMethodOverride" "ContributionMethod","employerValueOverride" DOUBLE PRECISION,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmployeeBenefit_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmployeeBenefit_payrollProfileId_benefitPlanId_key" ON "EmployeeBenefit"("payrollProfileId","benefitPlanId"); CREATE INDEX "EmployeeBenefit_organizationId_idx" ON "EmployeeBenefit"("organizationId");
CREATE TABLE "PayrollDeductionDefinition" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"creditorName" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PayrollDeductionDefinition_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PayrollDeductionDefinition_organizationId_name_key" ON "PayrollDeductionDefinition"("organizationId","name");
CREATE TABLE "EmployeeDeduction" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"payrollProfileId" TEXT NOT NULL,"deductionDefinitionId" TEXT NOT NULL,"method" "ContributionMethod" NOT NULL DEFAULT 'FIXED_AMOUNT',"value" DOUBLE PRECISION NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmployeeDeduction_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmployeeDeduction_payrollProfileId_deductionDefinitionId_key" ON "EmployeeDeduction"("payrollProfileId","deductionDefinitionId"); CREATE INDEX "EmployeeDeduction_organizationId_idx" ON "EmployeeDeduction"("organizationId");
ALTER TABLE "PayrollSettings" ADD CONSTRAINT "PayrollSettings_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmployeePayrollProfile" ADD CONSTRAINT "EmployeePayrollProfile_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmployeePayrollProfile" ADD CONSTRAINT "EmployeePayrollProfile_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BenefitPlan" ADD CONSTRAINT "BenefitPlan_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmployeeBenefit" ADD CONSTRAINT "EmployeeBenefit_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmployeeBenefit" ADD CONSTRAINT "EmployeeBenefit_payrollProfileId_fkey" FOREIGN KEY ("payrollProfileId") REFERENCES "EmployeePayrollProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmployeeBenefit" ADD CONSTRAINT "EmployeeBenefit_benefitPlanId_fkey" FOREIGN KEY ("benefitPlanId") REFERENCES "BenefitPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PayrollDeductionDefinition" ADD CONSTRAINT "PayrollDeductionDefinition_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmployeeDeduction" ADD CONSTRAINT "EmployeeDeduction_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmployeeDeduction" ADD CONSTRAINT "EmployeeDeduction_payrollProfileId_fkey" FOREIGN KEY ("payrollProfileId") REFERENCES "EmployeePayrollProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmployeeDeduction" ADD CONSTRAINT "EmployeeDeduction_deductionDefinitionId_fkey" FOREIGN KEY ("deductionDefinitionId") REFERENCES "PayrollDeductionDefinition"("id") ON DELETE CASCADE ON UPDATE CASCADE;
